16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Digits(fraction = 0, integer = 10)
49	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
56	    private Set<Pet> pets;
57	
58	    public String getAddress() {
59	        return this.address;
60	    }
61	
62	    public void setAddress(String address) {
63	        this.address = address;
64	    }
65	
66	    public String getCity() {
67	        return this.city;
68	    }
69	
70	    public void setCity(String city) {
71	        this.city = city;
72	    }
73	
74	    public String getTelephone() {
75	        return this.telephone;
76	    }
77	
78	    public void setTelephone(String telephone) {
79	        this.telephone = telephone;
80	    }
81	
82	    public String getEmail() {
83	        return this.email;
84	    }
85	
86	    public void setEmail(String email) {
87	        this.email = email;
88	    }
89	
90	    /**
91	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
92	     */
93	    @Transient
94	    public String getDisplayName() {
95	        return this.getLastName() + ", " + this.getFirstName();
96	    }
97	
98	    /**
99	     * The owner's initials: the upper-cased first letters of firstName and
100	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
101	     */
102	    @Transient
103	    public String getInitials() {
104	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
105	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
106	    }
107	
108	    protected Set<Pet> getPetsInternal() {
109	        if (this.pets == null) {
110	            this.pets = new HashSet<>();
111	        }
112	        return this.pets;
113	    }
114	
115	    protected void setPetsInternal(Set<Pet> pets) {
116	        this.pets = pets;
117	    }
118	
119	    public List<Pet> getPets() {
120	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
121	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
122	        return Collections.unmodifiableList(sortedPets);
123	    }
124	
125	    public void setPets(List<Pet> pets) {
126	        this.pets = new HashSet<>(pets);
127	    }
128	
129	    public void addPet(Pet pet) {
130	        getPetsInternal().add(pet);
131	        pet.setOwner(this);
132	    }
133	
134	    /**
135	     * Return the Pet with the given name, or null if none found for this Owner.
136	     *
137	     * @param name to test
138	     * @return true if pet name is already in use
139	     */
140	    public Pet getPet(String name) {
141	        return getPet(name, false);
142	    }
143	
144	    /**
145	     * Return the Pet with the given name, or null if none found for this Owner.
146	     *
147	     * @param name to test
148	     * @return true if pet name is already in use
149	     */
150	    public Pet getPet(String name, boolean ignoreNew) {
151	        name = name.toLowerCase();
152	        for (Pet pet : getPetsInternal()) {
153	            if (!ignoreNew || !pet.isNew()) {
154	                String compName = pet.getName();
155	                compName = compName.toLowerCase();
156	                if (compName.equals(name)) {
157	                    return pet;
158	                }
159	            }
160	        }
161	        return null;
162	    }
163	
164	    public Pet getPet(Integer petId) {
165	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
166	    }
167	
168	    @Override
169	    public String toString() {
170	        return new ToStringCreator(this)
171	
172	            .append("id", this.getId())
173	            .append("new", this.isNew())
174	            .append("lastName", this.getLastName())
175	            .append("firstName", this.getFirstName())
176	            .append("address", this.address)
177	            .append("city", this.city)
178	            .append("telephone", this.telephone)
179	            .append("email", this.email)
180	            .toString();
181	    }
182	}
