1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	
7	public class ApplyOwner {
8	
9	    public void service(@Val Owner owner, @Val OwnerFieldsDto request) {
10	        owner.setAddress(request.getAddress());
11	        owner.setCity(request.getCity());
12	        owner.setFirstName(request.getFirstName());
